SELECT /*selectMasterMpSoBuyerWarhsngProcList*/ BUYER_COM_NAME , AGENT_COM_NAME , PO_NO , PO_SEQ , REF_PR_NO , BUYER_ITEM_NO , DESCRIPTION , SPECIFICATION , UNIT_MEASURE , ITEM_QTY , GR_QTY , AVAIL_GR_QTY --, NVL(INV_QTY,0) - NVL(GR_QTY,0) AS AVAIL_GR_QTY , INV_DATE , UNIT_PRICE , INV_UNIT_AMT , INV_NO , INV_SEQ , BUYER , AGENT , IV_QTY , AGENT_PRICE , REF_IF_NO , BYIT_COMORG_CODE , TR_BUYER , INV_QTY , CONTRACT_NO , CONTRACT_SEQ , CLOSE_DATE , CARD_USE_FLAG , CARD_CONFIRM_NO , PARCEL_COM_CODE , F_GET_CMCD_NAME('C019', PARCEL_COM_CODE) AS PARCEL_COM_NAME , PARCEL_INV_NO , REPLACE(INV_NO_URL,'param',PARCEL_INV_NO) AS REAL_INV_NO_URL -- 택배사_매핑 경로 , EXP_CUR , EXP_CUR_PRICE , EXP_FOR_UNIT_PRICE , EXP_FOR_ITEM_AMT , S.MAIL_SEND_FLAG , (SELECT TO_CHAR(MAX(MNG.CREATE_DATE),'YYYY/MM/DD HH24:MI') FROM KEP_USE_PGM_MNG MNG WHERE MNG.PGM_NAME = 'GR_NOTICE_MB' AND MNG.PGM_VARIABLE = S.BUYER||S.PO_NO||S.PO_SEQ||S.INV_NO||S.INV_SEQ) AS MAIL_SEND_DATE , S.LEGACY_PO_NO , S.BUYER||S.PO_NO||S.PO_SEQ||S.INV_NO||S.INV_SEQ AS PGM_VARIABLE , LEGACY_IV_SERIAL_DT , PROCESS_TYPE , WAREHOUSE_CODE , (SELECT DECODE(COUNT(*),0,'N','Y') FROM ICOMCOD1 WHERE TYPE = 'W001' AND TEXT1 = S.BUYER) AS WAREHOUSE_BUYER_YN FROM ( SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = B.BUYER) AS BUYER_COM_NAME -- 구매사 0 , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AS AGENT_COM_NAME -- 공급사 1 , B.PO_NO -- 발주번호 2 , B.PO_SEQ -- 발주항번 3 , B.REF_PR_NO -- 관리번호 4 , B.BUYER_ITEM_NO -- 제품코드 5 , B.DESCRIPTION -- 품명 6 , B.SPECIFICATION -- 규격 7 , B.UNIT_MEASURE -- 단위 8 , B.ITEM_QTY -- 발주수량 9 , NVL(B.GR_QTY,0) AS GR_QTY -- 기입고수량 10 , DECODE(B.PROCESS_TYPE,'0',C.INV_QTY- NVL(C.GR_QTY,0) ,D.INV_QTY- NVL(D.BUYER_GR_QTY,0)) AS AVAIL_GR_QTY -- 입고가능수량 11 --, DECODE(B.PROCESS_TYPE,'0',C.INV_QTY,D.INV_QTY) AS AVAIL_GR_QTY -- 입고가능수량 11 --, NVL(B.ITEM_QTY,0) - NVL(B.GR_QTY,0) AS AVAIL_GR_QTY , '' AS INV_DATE -- 입고일 12 , B.UNIT_PRICE -- 판매단가 13 , DECODE(B.PROCESS_TYPE,0,NVL(C.INV_QTY,0)* C.UNIT_PRICE,NVL(D.INV_QTY,0)* D.UNIT_PRICE) AS INV_UNIT_AMT -- 금액 14 , DECODE(B.PROCESS_TYPE,'0',C.INV_NO,D.INV_NO) AS INV_NO -- 15 , DECODE(B.PROCESS_TYPE,'0',C.INV_SEQ,D.INV_SEQ) AS INV_SEQ -- 16 , B.BUYER -- 17 , A.AGENT -- 18 , NVL(B.IV_QTY,0) AS IV_QTY -- 19 , B.AGENT_PRICE -- 20 , B.REF_IF_NO -- 21 , B.BYIT_COMORG_CODE -- 22 , DECODE(B.PROCESS_TYPE,'0',B.BUYER,D.WAREHOUSE_CODE) AS TR_BUYER -- 23 , DECODE(B.PROCESS_TYPE,'0',NVL(C.INV_QTY,0),NVL(D.INV_QTY,0)) AS INV_QTY -- 24 --, B.IV_QTY AS INV_QTY , B.CONTRACT_NO -- 25 , B.CONTRACT_SEQ -- 26 , (SELECT LAST_CLOSE_DATE FROM MIS_CLOSDATE WHERE BUYER = B.BUYER) AS CLOSE_DATE -- 27 , (SELECT CARD_USE_FLAG FROM icomprhd WHERE BUYER = B.BUYER and pr_no = b.pr_no) AS CARD_USE_FLAG -- 28 , (SELECT CARD_CONFIRM_NO FROM icomprhd WHERE BUYER = B.BUYER and pr_no = b.pr_no) AS CARD_CONFIRM_NO -- 29 , DECODE(B.PROCESS_TYPE,'0',E.PARCEL_COM_CODE,D.DELIVERY_COMPANY) AS PARCEL_COM_CODE , DECODE(B.PROCESS_TYPE,'0',E.PARCEL_INV_NO,D.DELIVERY_NO) AS PARCEL_INV_NO , ( SELECT A1.TEXT5 FROM ICOMCOD1 A1 WHERE A1.TYPE = 'C019' and A1.CODE = DECODE(B.PROCESS_TYPE,'0',E.PARCEL_COM_CODE,D.DELIVERY_COMPANY)) AS INV_NO_URL -- 택배사_경로 , F.EXP_CUR , F.EXP_CUR_PRICE , F.EXP_FOR_UNIT_PRICE , F.EXP_FOR_ITEM_AMT , (SELECT DECODE(COUNT(IMP.SLG_ID),0,'N','Y') FROM BNTSLGDEF DEF , BNTSLGIMP IMP WHERE DEF.SLG_ID = IMP.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN DEF.OPEN_DATE AND DEF.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN IMP.OPEN_DATE AND IMP.CLOSE_DATE AND IMP.COM_CODE = B.BUYER AND DEF.SLG_ID = 'P07-0000026') AS MAIL_SEND_FLAG , B.LEGACY_PO_NO , C.LEGACY_IV_SERIAL_DT , B.PROCESS_TYPE , DECODE(B.PROCESS_TYPE, '2', B.WAREHOUSE_CODE, DECODE(B.PROCESS_TYPE, '3', D.WAREHOUSE_CODE, A.AGENT)) AS WAREHOUSE_CODE FROM ICOMPOHD A, ICOMPODT B, ICOMIVDT C, WMSIVDT D, ICOMIVHD E, ICOMPRDT F WHERE A.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND B.BUYER = #{st_buyer_code}
AND A.AGENT = #{st_agent_code}
AND B.PO_NO = #{st_po_no}
AND B.BUYER_ITEM_NO LIKE UPPER(#{st_buyer_item_no}||'%')
AND B.REF_PR_NO LIKE UPPER(#{st_ref_no}||'%')
AND B.LEGACY_PO_NO = #{st_legacy_po_no}
AND A.BUYER = B.BUYER AND A.PO_NO = B.PO_NO AND B.BUYER = C.BUYER AND B.PO_NO = C.PO_NO AND B.PO_SEQ = C.PO_SEQ AND B.BUYER = F.BUYER AND B.PR_NO = F.PR_NO AND B.PR_SEQ = F.PR_SEQ AND C.BUYER = D.BUYER(+) AND C.INV_NO = D.S_INV_NO(+) AND C.INV_SEQ = D.S_INV_SEQ(+) AND C.BUYER = E.BUYER AND C.INV_NO = E.INV_NO AND D.STATUS(+) <> 'D' AND A.STATUS <> 'D' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND E.STATUS <> 'D' AND F.STATUS <> 'D' AND (NVL(ABS(B.IV_QTY),0) <> NVL(abs(B.GR_QTY),0)) AND B.ITEM_QTY <> B.GR_QTY AND DECODE(B.PROCESS_TYPE,'0',C.INV_NO, D.INV_NO ) IS NOT NULL AND DECODE(B.PROCESS_TYPE,'0',NVL(C.GR_QTY,0), NVL(D.BUYER_GR_QTY,0)) <> DECODE(B.PROCESS_TYPE,'0',NVL(C.INV_QTY,0), NVL(D.INV_QTY,0))
AND B.REG_NO != 'OF'
AND B.REG_NO = 'OF'
) S ORDER BY S.PO_NO, S.PO_SEQ, S.BUYER_ITEM_NO

