C.INV_QTY,0)* C.UNIT_PRICE,NVL(D.INV_QTY,0)* D.UNIT_PRICE) AS INV_UNIT_AMT -- 금액 14 , DECODE(B.PROCESS_TYPE,'0',C.INV_NO,D.INV_NO) AS INV_NO -- 15 , DECODE(B.PROCESS_TYPE,'0',C.INV_SEQ,D.INV_SEQ) AS INV_SEQ -- 16 , B.BUYER -- 17 , A.AGENT -- 18 , NVL(B.IV_QTY,0) AS IV_QTY -- 19 , B.AGENT_PRICE -- 20 , B.REF_IF_NO -- 21 , B.BYIT_COMORG_CODE -- 22 , DECODE(B.PROCESS_TYPE,'0',B.BUYER,D.WAREHOUSE_CODE) AS TR_BUYER -- 23 , DECODE(B.PROCESS_TYPE,'0',NVL(C.INV_QTY,0),NVL(D.INV_QTY,0)) AS INV_QTY -- 24 --, B.IV_QTY AS INV_QTY , B.CONTRACT_NO -- 25 , B.CONTRACT_SEQ -- 26 , (SELECT LAST_CLOSE_DATE FROM MIS_CLOSDATE WHERE BUYER = B.BUYER) AS CLOSE_DATE -- 27 , (SELECT CARD_USE_FLAG FROM icomprhd WHERE BUYER = B.BUYER and pr_no = b.pr_no) AS CARD_USE_FLAG -- 28 , (SELECT CARD_CONFIRM_NO FROM icomprhd WHERE BUYER = B.BUYER and pr_no = b.pr_no) AS CARD_CONFIRM_NO -- 29 , DECODE(B.PROCESS_TYPE,'0',E.PARCEL_COM_CODE,D.DELIVERY_COMPANY) AS PARCEL_COM_CODE , DECODE(B.PROCESS_TYPE,'0',E.PARCEL_INV_NO,D.DELIVERY_NO) AS PARCEL_INV_NO , ( SELECT A1.TEXT5 FROM ICOMCOD1 A1 WHERE A1.TYPE = 'C019' and A1.CODE = DECODE(B.PROCESS_TYPE,'0',E.PARCEL_COM_CODE,D.DELIVERY_COMPANY)) AS INV_NO_URL -- 택배사_경로 , F.EXP_CUR , F.EXP_CUR_PRICE , F.EXP_FOR_UNIT_PRICE , F.EXP_FOR_ITEM_AMT , (SELECT DECODE(COUNT(IMP.SLG_ID),0,'N','Y') FROM BNTSLGDEF DEF , BNTSLGIMP IMP WHERE DEF.SLG_ID = IMP.SLG_ID AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN DEF.OPEN_DATE AND DEF.CLOSE_DATE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN IMP.OPEN_DATE AND IMP.CLOSE_DATE AND IMP.COM_CODE = B.BUYER AND DEF.SLG_ID = 'P07-0000026') AS MAIL_SEND_FLAG , B.LEGACY_PO_NO , C.LEGACY_IV_SERIAL_DT , B.PROCESS_TYPE , DECODE(B.PROCESS_TYPE, '2', B.WAREHOUSE_CODE, DECODE(B.PROCESS_TYPE, '3', D.WAREHOUSE_CODE, A.AGENT)) AS WAREHOUSE_CODE , C.DELIVERY_DATE AS DELIVERY_DATE , NVL(C.AP_BILL_FLAG,'N') AS AP_BILL_FLAG FROM ICOMPOHD A, ICOMPODT B, ICOMIVDT C, WMSIVDT D, ICOMIVHD E, ICOMPRDT F WHERE A.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND B.BUYER = #{st_buyer_code}
