/*updateMasterMpSoBuyerWarhsngProcPodt*/
UPDATE ICOMPODT
SET
	GR_QTY = NVL(GR_QTY,0) + ${AVAIL_GR_QTY}
WHERE
		BUYER 	= #{BUYER}
	AND SELLER  = 'KRKORE0001'
	AND PO_NO   = #{PO_NO}
	AND PO_SEQ  = #{PO_SEQ}
	AND STATUS != 'D'
	AND ITEM_QTY >= (NVL(GR_QTY,0) + ${AVAIL_GR_QTY})

mapper.select:

/*selectMasterMpSoBuyerWarhsngProcessInfo*/
SELECT 
	  HD.PROCESS_TYPE
	, DECODE(PO.PROCESS_TYPE, '2', PO.WAREHOUSE_CODE, HD.AGENT) AS WAREHOUSE_CODE
FROM ICOMPODT PO, ICOMPOHD HD
WHERE
		PO.BUYER 	= #{BUYER}
	AND PO.PO_NO 	= #{PO_NO}
	AND PO.PO_SEQ 	= #{PO_SEQ}
	AND PO.BUYER 	= HD.BUYER
	AND PO.PO_NO 	= HD.PO_NO
	AND PO.STATUS <> 'D'
	AND HD.STATUS <> 'D'

