/*updateMasterMpSoBuyerWarhsngProcIvhd*/
UPDATE ICOMIVHD 
SET 
	GR_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
WHERE
		BUYER   = #{BUYER}
	AND SELLER  = 'KRKORE0001'
	AND INV_NO  = #{INV_NO}
	AND STATUS != 'D'


/*updateMasterMpSoBuyerWarhsngProcWmsIvdt*/
UPDATE WMSIVDT A 
SET
	  A.BUYER_GR_QTY = NVL(BUYER_GR_QTY,0) + ${AVAIL_GR_QTY}
	, CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
	, CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE 
		A.BUYER  = #{BUYER}
	AND A.WAREHOUSE_CODE = #{WAREHOUSE_CODE}
	AND A.SELLER   = 'KRKORE0001'
	AND A.INV_NO   = #{INV_NO}
	AND A.INV_SEQ  = #{INV_SEQ}
	AND A.STATUS  != 'D'

