/*selectMasterMpSoBuyerWarhsngProcCarStockCheck*/
SELECT COUNT(1) AS CNT
FROM CAR_STOCK CAR
WHERE CAR.BUYER = #{BUYER}
AND CAR.BUYER_ITEM_NO = #{BUYER_ITEM_NO}

