/*insertMasterMpSoBuyerWarhsngProcCarStock*/
INSERT INTO CAR_STOCK (
	BUYER
	,BUYER_ITEM_NO
	,BYIT_COMORG_CODE
	,GR_QTY
	,IV_QTY
	,ADD_USER_ID
	,ADD_DATE
	,CHANGE_USER_ID
	,CHANGE_DATE
	,STATUS
) VALUES (
	#{BUYER}
	,#{BUYER_ITEM_NO}
	,(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = #{BUYER})
	,#{AVAIL_GR_QTY}
	,0
	,#{st_user_id}
	,SYSDATE
	,#{st_user_id}
	,SYSDATE
	,'C'
)


/*updateMasterMpSoBuyerWarhsngProcCarStockAdd*/
UPDATE CAR_STOCK SET
GR_QTY = (GR_QTY+#{AVAIL_GR_QTY})
,CHANGE_USER_ID = #{st_user_id}
,CHANGE_DATE = SYSDATE
WHERE BUYER = #{BUYER}
AND BUYER_ITEM_NO = #{BUYER_ITEM_NO}


/*insertMasterMpSoBuyerWarhsngProcCarStockGrdt*/
INSERT INTO CAR_STOCK_GRDT (
	BUYER
	,GR_NO
	,GR_SEQ
	,BYIT_COMORG_CODE
	,BUYER_ITEM_NO
	,GR_QTY
	,ADD_USER_ID
	,ADD_DATE
	,CHANGE_USER_ID
	,CHANGE_DATE
	,STATUS
) VALUES (
	#{BUYER}
	,#{GR_NO}
	,TO_CHAR(#{GR_SEQ},'FM000000')
	,(SELECT BYCA_COMORG_CODE FROM ICOMCMPY WHERE COM_CODE = #{BUYER})
	,#{BUYER_ITEM_NO}
	,#{AVAIL_GR_QTY}
	,#{st_user_id}
	,SYSDATE
	,#{st_user_id}
	,SYSDATE
	,'C'
)

