		 /*updateMsterMpSoBuyerWarhsngProcDDateIvdt_v2*/
		UPDATE	ICOMIVDT IVDT
SET		IVDT.DELIVERY_DATE = #{INV_DATE},
		IVDT.CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
		IVDT.CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE	IVDT.BUYER = #{BUYER}
AND		IVDT.INV_NO = #{INV_NO}
AND		IVDT.INV_SEQ = #{INV_SEQ}
AND		IVDT.STATUS <> 'D'
